import{_ as l,o as r,c as t,a3 as i,j as e,a}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/verwaltung-schule-allgemeine-angaben.png",u="/bilder/schueler/verwaltung-schule-allgemeine-angaben-allgemeine-angaben.png",g="/bilder/schueler/verwaltung-schule-allgemeine-angaben-logo-loeschdialog.png",d="/bilder/schueler/verwaltung-schule-allgemeine-angaben-organisatorische-angaben.png",h="/bilder/schueler/verwaltung-schule-allgemeine-angaben-gliederungen-leer.png",c="/bilder/schueler/verwaltung-schule-allgemeine-angaben-gliederungen-gymnasium-neue-gliederung.png",o="/bilder/schueler/verwaltung-schule-allgemeine-angaben-gliederung-bk.png",m="/bilder/schueler/verwaltung-schule-allgemeine-angaben-angabenzu-abschnitten.png",p="/bilder/schueler/verwaltung-schule-allgemeine-angaben-schulleitung.png",_=JSON.parse('{"title":"Allgemeine Schuldaten und Organisation einstellen","description":"","frontmatter":{"title":"Allgemeine Schuldaten und Organisation einstellen","source_pageid":230,"source_revision":4735},"headers":[],"relativePath":"schild3/schueler/allgemeine-angaben-verwaltung-schule.md","filePath":"schild3/schueler/allgemeine-angaben-verwaltung-schule.md"}'),b={name:"schild3/schueler/allgemeine-angaben-verwaltung-schule.md"};function f(S,n,k,w,z,v){return r(),t("div",null,[...n[0]||(n[0]=[i('<h1 id="allgemeine-schuldaten-und-organisation-einstellen" tabindex="-1">Allgemeine Schuldaten und Organisation einstellen <a class="header-anchor" href="#allgemeine-schuldaten-und-organisation-einstellen" aria-label="Permalink to &quot;Allgemeine Schuldaten und Organisation einstellen&quot;">​</a></h1><p>Pflegen Sie Schuldaten, organisatorische Angaben, Gliederungen und Lernabschnitte. Die Angaben werden auch für Reports verwendet; Änderungen mit Wirkung auf den Schulkatalog sind gesondert zu melden.</p><p>Unter diesem Programmpunkt werden die Grundeinstellungen zur Schule vorgenommen.</p><h2 id="aufbau-und-herkunft-der-schuldaten" tabindex="-1">Aufbau und Herkunft der Schuldaten <a class="header-anchor" href="#aufbau-und-herkunft-der-schuldaten" aria-label="Permalink to &quot;Aufbau und Herkunft der Schuldaten&quot;">​</a></h2><p><a href="/bilder/schueler/verwaltung-schule-allgemeine-angaben.png"><img src="'+s+'" alt="Die Allgemeinen Angaben zur Schule eintragen." loading="lazy"></a></p><p><em>Die Allgemeinen Angaben zur Schule eintragen.</em></p><p>Nach dem Anlegen der Datenbank werden die Angaben aus dem mit installierten Katalog der Schulen von IT.NRW übernommen. Diese Angaben können Sie nachträglich verändern.</p><p>Angaben, die sich auf den Katalog von IT.NRW auswirken sollen, müssen im Schulportal geändert werden oder direkt an IT.NRW gemeldet werden.</p><p>Das Fenster ist gegliedert in 5 Bereiche</p><ul><li>Allgemeine Angaben (links oben)</li><li>Organisatorische Angaben (links unten)</li><li>Gliederungen (rechts oben)</li><li>Angaben zu Abschnitten (rechts mittig)</li><li>Schulleitung (rechts unten)</li></ul><h2 id="schulname-und-kontaktdaten" tabindex="-1">Schulname und Kontaktdaten <a class="header-anchor" href="#schulname-und-kontaktdaten" aria-label="Permalink to &quot;Schulname und Kontaktdaten&quot;">​</a></h2><p><a href="/bilder/schueler/verwaltung-schule-allgemeine-angaben-allgemeine-angaben.png"><img src="'+u+'" alt="Die Daten zu Bezeichnung und Adresse der Schule." loading="lazy"></a></p><p><em>Die Daten zu Bezeichnung und Adresse der Schule.</em></p><p>Die hier eingetragenen Informationen werden bei den Reports zur Verfügung stehen und in der Regel in Briefköpfen genutzt. Sie sollten hier die Angaben einsetzen, die für Ihre Schule am sinnvollsten erscheinen.</p>',14),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),a("Wichtig")]),e("p",null,"Änderungen der Adress- und Kontaktdaten der Schule müssen an IT.NRW gemeldet werden.")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),a("Tipp")]),e("p",null,"Der Link hier im Fenster kann angeklickt werden und öffnet die angezeigte URL des Bildungsportals im Internetbrowser.")],-1),i('<h2 id="mehrzeiliger-schulname" tabindex="-1">Mehrzeiliger Schulname <a class="header-anchor" href="#mehrzeiliger-schulname" aria-label="Permalink to &quot;Mehrzeiliger Schulname&quot;">​</a></h2><p>Bitte beachten Sie, dass Sie den Namen der Schule in 3 Zeilen eintragen können. Zu lange Namen in einer Zeile lassen sich in Briefköpfen nicht mehr sinnvoll darstellen. Vereinzelt wird in manchen Reportvorlagen der Kürze halber nur die erste Zeile des Namens verwendet.</p><p>Die drei oberen Eingabebereiche können über den Reportdesigner über <em>Bezeichnung1</em> bis <em>Bezeichung3</em> abgerufen werden.</p><h3 id="schullogo" tabindex="-1">Schullogo <a class="header-anchor" href="#schullogo" aria-label="Permalink to &quot;Schullogo&quot;">​</a></h3><p><a href="/bilder/schueler/verwaltung-schule-allgemeine-angaben-logo-loeschdialog.png"><img src="'+g+'" alt="Dialog, ob das Logo gelöscht werden soll." loading="lazy"></a></p><p><em>Dialog, ob das Logo gelöscht werden soll.</em></p><p>Neben der Schulnummer wird das Logo der Schule angezeigt. Dieses Logo wird in vielen Report-Vorlagen verwendet.</p><p>Es kann über das <strong>Ordnersymbol</strong> hinzugefügt werden. Damit kann eine lokal vorhandene Grafik-Datei als neues Logo ausgewählt werden. Achten Sie bei der Auswahl der Grafik auf eine entsprechende Qualität.</p><p>Soll das Logo gelöscht werden muss auf das <strong>Radierer-Symbol</strong> geklickt werden.</p><p>Es öffnet sich ein Bestätigungsdialog. Wird mit <strong>Ja</strong> bestätigt wird das Logo aus der Datenbank gelöscht.</p><h3 id="anderungen-an-it-nrw-melden" tabindex="-1">Änderungen an IT.NRW melden <a class="header-anchor" href="#anderungen-an-it-nrw-melden" aria-label="Permalink to &quot;Änderungen an IT.NRW melden&quot;">​</a></h3><p>Zu beachten ist vor allem der Link zum Schulministierum. Sofern sich der Name, die Anschrift oder die Kontaktdaten der Schule geändert haben, folgen Sie bitte diesem Link und teilen die Änderungen mit.</p><h2 id="organisatorische-angaben" tabindex="-1">Organisatorische Angaben <a class="header-anchor" href="#organisatorische-angaben" aria-label="Permalink to &quot;Organisatorische Angaben&quot;">​</a></h2><p><a href="/bilder/schueler/verwaltung-schule-allgemeine-angaben-organisatorische-angaben.png"><img src="'+d+'" alt="Schild Verwaltung Schule AllgemeineAngaben OrganisatorischeAngaben.png" loading="lazy"></a></p><p><strong>Aktuelles Schuljahr und Abschnitt:</strong> Hier legen Sie den aktiven Zeitraum der Datenbank fest. Dieser kann vom Lernabschnitt einzelner Schülerinnen und Schüler abweichen; solche Datensätze werden rosa angezeigt. Im Regelfall stimmen die Zeiträume überein.</p><p>Wenn Sie einen früheren Abschnitt für die Datenbank aktivieren, bleiben die vorhandenen Schülerdaten unverändert. Durch diese Auswahl werden keine Einträge gelöscht.</p><p><strong>Jahrg.Stufen pro Jahr</strong> und <strong>Abschnitte pro Jahrg.Stufe</strong> Hier wird angezeigt, wie viele das Schuljahr hat. Da SchILD-NRW auf zwei Halbjahr/Semester festgelegt ist, sind die Eingabemöglichkeiten gesperrt und grau dargestellt.</p><p><strong>Dauer einer Unterrichtseinheit*</strong> Standardeinstellung ist 45 Minuten. Hier kann allerdings auf ein anderes Minutenmodell umgestellt werden. Dies ist nur relevant bei der Erzeugung der UVD.txt für die Statistik. Hier wird zu Beginn der Datei übermittelt, wie viele Minuten eine Unterrichtseinheit hat.</p><h2 id="gliederungen" tabindex="-1">Gliederungen <a class="header-anchor" href="#gliederungen" aria-label="Permalink to &quot;Gliederungen&quot;">​</a></h2><p><a href="/bilder/schueler/verwaltung-schule-allgemeine-angaben-gliederungen-leer.png"><img src="'+h+'" alt="Die Gliederung ***: Standard für diese Schulform ist an vielen Schulen die einzige Gliederung." loading="lazy"></a></p><p><em>Die Gliederung <strong>***: Standard für diese Schulform</strong> ist an vielen Schulen die einzige Gliederung.</em></p><p>Hier werden alle Gliederungen (Bildungsgänge) einer Schule aufgeführt.</p><p>An den meisten Schulformen gibt es nur den Bildungsgang &quot;<strong>***-Standard für diese Schulform</strong>&quot; und oft reicht diese oder noch ein bis zwei weitere Gliederungen, um die Schule abzubilden.</p><p>An Berufskollegs und Weiterbildungskollegs werden hier alle Gliederungen eingetragen, für die es Fachklassen an der Schule gibt. SchILD-NRW richtet sich dabei nach den Bezeichnungen der Statistik.</p><p>An einigen Schulen gibt es auch mehrere Gliederungen, die dann in diesem Fenster aufgeführt sein müssen.</p><p><a href="/bilder/schueler/verwaltung-schule-allgemeine-angaben-gliederungen-gymnasium-neue-gliederung.png"><img src="'+c+'" alt="Die an einem typischen Gymnasium einstellbaren Gliederungen." loading="lazy"></a></p><p><em>Die an einem typischen Gymnasium einstellbaren Gliederungen.</em></p><p>Einige Beispiele sind:</p><ul><li><em>Wiedereinrichter Gymnasium G9</em></li><li><em>auslaufende Bildungsgänge</em>, z.B. Hauptschule an der Sekundarschule</li><li><em>parallele Bildungsgänge</em>, z.B. H und R an der Sekundarschule</li><li><em>kath. Grundschule (RKB)</em>, hier entfällt die Standardgliederung</li></ul><p>Bitte informieren Sie sich, welche Gliederungen an Ihrer Schule aufgeführt sein müssen.</p><p>Um eine neue Gliederung anzulegen, klicken Sie zunächst auf das <strong>+</strong> und wählen Sie dann die passende Bezeichnung über das Aufklappmenü aus.</p><p>Anschließend wird das Kürzel automatisch eingetragen.</p><p>Im Bild sehen Sie exemplarisch die Eintragungsmöglichkeiten an einem Gymnasium.</p><p><a href="/bilder/schueler/verwaltung-schule-allgemeine-angaben-gliederung-bk.png"><img src="'+o+'" alt="An einem BK finden sich eine Vielzahl an Gliederungen." loading="lazy"></a></p><p><em>An einem BK finden sich eine Vielzahl an Gliederungen.</em></p><p>Ein Berufskolleg bietet hier viel mehr Gliederungen für die unterschiedliche Bildungsgänge und Abschlüsse an.</p><p>Der Screenshot zeigt ungefähr die Hälfte der eingerichteten Gliederungen.</p><h2 id="angaben-zu-abschnitten" tabindex="-1">Angaben zu Abschnitten <a class="header-anchor" href="#angaben-zu-abschnitten" aria-label="Permalink to &quot;Angaben zu Abschnitten&quot;">​</a></h2><p><a href="/bilder/schueler/verwaltung-schule-allgemeine-angaben-angabenzu-abschnitten.png"><img src="'+m+'" alt="Schild Verwaltung Schule AllgemeineAngaben AngabenzuAbschnitten.png" loading="lazy"></a></p><p>Legen Sie hier fest, wie die Abschnitte und Abkürzungen benannt werden sollen.</p><p>Die hier eingetragenen Kürzel werden in Reports und Übersichten verwendet.</p><h2 id="schulleitung" tabindex="-1">Schulleitung <a class="header-anchor" href="#schulleitung" aria-label="Permalink to &quot;Schulleitung&quot;">​</a></h2><p><a href="/bilder/schueler/verwaltung-schule-allgemeine-angaben-schulleitung.png"><img src="'+p+'" alt="Eintrag der Schulleitung und stellvertretenden Schulleitung. Es werden auch die Zeiträume ehemaliger Schulleitungen erfasst." loading="lazy"></a></p><p><em>Eintrag der Schulleitung und stellvertretenden Schulleitung. Es werden auch die Zeiträume ehemaliger Schulleitungen erfasst.</em></p><p>Geben Sie hier die Informationen zur <em>Schulleitung</em> und zur <em>stellvertretenden</em> Schulleitung ein.</p><p>Über das <strong>+</strong> oberhalb der Tabelle können Sie eine neue Zeile anlegen. Wählen Sie dann aus, für welche Funktion Sie einen Eintrag machen. In der zweiten Spalte können Sie eintragen, welche Lehrkraft diese Funktion ausübt.</p><p>Um den Zeitraum, in dem diese Lehrkraft diese Funktion ausgefüllt hat eintragen zu können, muss links neben der Eintragung auf das kleine <strong>+</strong> geklickt werden. Dies erleichtert nach einem Leitungswechsel den nachträglichen Druck von Zeugnissen aus vergangenen Schuljahren.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Allgemeine_Angaben_(Verwaltung_Schule)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4735.</p>',49)])])}const D=l(b,[["render",f]]);export{_ as __pageData,D as default};
